        (1000088369, 61504, 1000041858, 1000041898, N'SC2603310045', N'SC2603270084', N'SP2603311000045993', N'SP2603261000044859'),
        (1000088370, 61503, 1000041859, 1000041899, N'SC2603310046', N'SC2603270085', N'SP2603311000045992', N'SP2603261000044858'),
        (1000088371, 61502, 1000041860, 1000041900, N'SC2603310047', N'SC2603270086', N'SP2603311000045991', N'SP2603261000044857'),
        (1000088372, 61501, 1000041861, 1000041901, N'SC2603310048', N'SC2603270087', N'SP2603311000045990', N'SP2603261000044856'),
        (1000088373, 61500, 1000041862, 1000041902, N'SC2603310049', N'SC2603270088', N'SP2603311000045989', N'SP2603261000044855'),
        (1000088374, 61499, 1000041863, 1000041903, N'SC2603310050', N'SC2603270089', N'SP2603311000045988', N'SP2603261000044854'),
        (1000088375, 61498, 1000041864, 1000041904, N'SC2603310051', N'SC2603270090', N'SP2603311000045987', N'SP2603261000044853'),
        (1000088376, 61497, 1000041865, 1000041905, N'SC2603310052', N'SC2603270091', N'SP2603311000045986', N'SP2603261000044852'),
        (1000088377, 61496, 1000041866, 1000041906, N'SC2603310053', N'SC2603270092', N'SP2603311000045985', N'SP2603261000044851'),
        (1000088378, 61495, 1000041867, 1000041907, N'SC2603310054', N'SC2603270093', N'SP2603311000045984', N'SP2603261000044850'),
        (1000088379, 61494, 1000041868, 1000041908, N'SC2603310055', N'SC2603270094', N'SP2603311000045983', N'SP2603261000044849'),
