        (1000088382, 61491, 1000041871, 1000041911, N'SC2603310058', N'SC2603270097', N'SP2603311000045980', N'SP2603261000044846'),
        (1000088383, 61490, 1000041872, 1000041912, N'SC2603310059', N'SC2603270098', N'SP2603311000045979', N'SP2603261000044845'),
        (1000088384, 61489, 1000041873, 1000041913, N'SC2603310060', N'SC2603270099', N'SP2603311000045978', N'SP2603261000044844'),
        (1000088385, 61488, 1000041874, 1000041914, N'SC2603310061', N'SC2603270100', N'SP2603311000045977', N'SP2603261000044843'),
        (1000088386, 61487, 1000041875, 1000041915, N'SC2603310062', N'SC2603270101', N'SP2603311000045976', N'SP2603261000044842'),
        (1000088387, 61486, 1000041876, 1000041916, N'SC2603310063', N'SC2603270102', N'SP2603311000045975', N'SP2603261000044841'),
        (1000088388, 61485, 1000041877, 1000041917, N'SC2603310064', N'SC2603270103', N'SP2603311000045974', N'SP2603261000044840'),
        (1000088389, 61484, 1000041878, 1000041918, N'SC2603310065', N'SC2603270104', N'SP2603311000045973', N'SP2603261000044839'),
        (1000088390, 61483, 1000041879, 1000041919, N'SC2603310066', N'SC2603270105', N'SP2603311000045972', N'SP2603261000044838'),
        (1000088391, 61568, 1000041880, 1000041920, N'SC2603310067', N'SC2603270106', N'SP2603311000045971', N'SW2603251000044822'),
        (1000088392, 61567, 1000041881, 1000041921, N'SC2603310068', N'SC2603270107', N'SP2603311000045970', N'SW2603251000044821')
    ) AS v(frozen_modid, frozen_kfu_id, frozen_u8_moid, frozen_kfu_u8id,
           frozen_u8_mocode, frozen_kfu_bom,
           frozen_u8_production_number, frozen_kfu_production_number)
)
SELECT
    SYSUTCDATETIME() AS read_at_utc,
    f.frozen_modid, f.frozen_kfu_id, f.frozen_kfu_u8id, f.frozen_kfu_bom,
    f.frozen_kfu_production_number,
    h.MoId AS code_match_moid, h.MoCode AS code_match_mocode,
    h.CreateDate AS code_match_create_date,
    d.MoDId AS code_match_modid, d.Status AS code_match_status,
    d.OrderType, d.OrderDId, d.OrderCode, d.Define25, d.Define28,
    CASE WHEN h.MoId IS NULL THEN N'FROZEN_KFU_ORDER_CODE_NOT_FOUND'
         ELSE N'CURRENT_CODE_CANDIDATE'
    END AS code_match_status_text
FROM FrozenScope AS f
LEFT JOIN dbo.mom_order AS h
    ON CONVERT(nvarchar(4000), h.MoCode) COLLATE Latin1_General_100_BIN2
       = CONVERT(nvarchar(4000), f.frozen_kfu_bom) COLLATE Latin1_General_100_BIN2
   AND DATALENGTH(CONVERT(nvarchar(4000), h.MoCode))
       = DATALENGTH(CONVERT(nvarchar(4000), f.frozen_kfu_bom))
LEFT JOIN dbo.mom_orderdetail AS d ON d.MoId = h.MoId
ORDER BY f.frozen_modid, h.MoId, d.MoDId;
